import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    def normalize(record):
        if not record:
            return ["", ""]
        if len(record) == 1:
            return [record[0], ""]
        if len(record) == 2:
            return record
        return [record[0], ",".join(record[1:])]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )
    header = next(reader, None)
    if header is None:
        return {"columns": [], "rows": []}

    return {
        "columns": normalize(header),
        "rows": [normalize(record) for record in reader],
    }
